/* UC13/UC14 demo seed. Run after the base schema and Sprint 2 additive scripts. */
USE SelfStorageFacilityDB;
GO
SET XACT_ABORT ON;
SET NOCOUNT ON;
GO
DECLARE @managerId UNIQUEIDENTIFIER = '11111111-1111-1111-1111-111111111111', @staffId UNIQUEIDENTIFIER = '22222222-2222-2222-2222-222222222222', @customerId UNIQUEIDENTIFIER = '33333333-3333-3333-3333-333333333333', @facilityId UNIQUEIDENTIFIER = '44444444-4444-4444-4444-444444444444', @unitId UNIQUEIDENTIFIER = '55555555-5555-5555-5555-555555555555', @reservationId UNIQUEIDENTIFIER = '66666666-6666-6666-6666-666666666666', @contractId UNIQUEIDENTIFIER = '77777777-7777-7777-7777-777777777777', @appointmentId UNIQUEIDENTIFIER = '88888888-8888-8888-8888-888888888888', @depositInvoiceId UNIQUEIDENTIFIER = '99999999-9999-9999-9999-999999999991', @rentInvoiceId UNIQUEIDENTIFIER = '99999999-9999-9999-9999-999999999992', @depositPaymentId UNIQUEIDENTIFIER = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa1', @rentPaymentId UNIQUEIDENTIFIER = 'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaa2', @pricingId UNIQUEIDENTIFIER, @typeId INT, @managerRoleId INT, @staffRoleId INT, @customerRoleId INT;
BEGIN TRANSACTION;
IF NOT EXISTS (SELECT 1 FROM dbo.ROLES WHERE role_name=N'FACILITY_MANAGER') INSERT dbo.ROLES(role_name,description) VALUES (N'FACILITY_MANAGER',N'Quản lý cơ sở');
IF NOT EXISTS (SELECT 1 FROM dbo.ROLES WHERE role_name=N'FACILITY_STAFF') INSERT dbo.ROLES(role_name,description) VALUES (N'FACILITY_STAFF',N'Nhân viên cơ sở');
IF NOT EXISTS (SELECT 1 FROM dbo.ROLES WHERE role_name=N'CUSTOMER') INSERT dbo.ROLES(role_name,description) VALUES (N'CUSTOMER',N'Khách hàng');
SELECT @managerRoleId=role_id FROM dbo.ROLES WHERE role_name=N'FACILITY_MANAGER'; SELECT @staffRoleId=role_id FROM dbo.ROLES WHERE role_name=N'FACILITY_STAFF'; SELECT @customerRoleId=role_id FROM dbo.ROLES WHERE role_name=N'CUSTOMER';
IF NOT EXISTS (SELECT 1 FROM dbo.USERS WHERE user_id=@managerId) INSERT dbo.USERS(user_id,role_id,email,password_hash,full_name,phone,status,created_at,email_verified) VALUES (@managerId,@managerRoleId,N'manager.demo@safebox.test',N'$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy',N'Manager Demo',N'0900000011',N'ACTIVE',SYSDATETIME(),1);
IF NOT EXISTS (SELECT 1 FROM dbo.USERS WHERE user_id=@staffId) INSERT dbo.USERS(user_id,role_id,email,password_hash,full_name,phone,status,created_at,email_verified) VALUES (@staffId,@staffRoleId,N'staff.demo@safebox.test',N'$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy',N'Staff Demo',N'0900000012',N'ACTIVE',SYSDATETIME(),1);
IF NOT EXISTS (SELECT 1 FROM dbo.USERS WHERE user_id=@customerId) INSERT dbo.USERS(user_id,role_id,email,password_hash,full_name,phone,status,created_at,email_verified) VALUES (@customerId,@customerRoleId,N'customer.demo@safebox.test',N'$2a$10$N9qo8uLOickgx2ZMRZoMyeIjZAgcfl7p92ldGxad68LJZdL17lhWy',N'Customer Demo',N'0900000013',N'ACTIVE',SYSDATETIME(),1);
IF NOT EXISTS (SELECT 1 FROM dbo.FACILITIES WHERE facility_id=@facilityId) INSERT dbo.FACILITIES(facility_id,name,address,phone,opening_time,closing_time,status) VALUES (@facilityId,N'SafeBox UC13-14 Demo',N'Đường Demo, Quận 7, Thành phố Hồ Chí Minh',N'0900000099','07:00','21:00',N'ACTIVE');
IF NOT EXISTS (SELECT 1 FROM dbo.USER_FACILITY_ASSIGNMENTS WHERE user_id=@managerId AND facility_id=@facilityId) INSERT dbo.USER_FACILITY_ASSIGNMENTS(assignment_id,user_id,facility_id,assigned_by,start_date,status) VALUES (NEWID(),@managerId,@facilityId,@managerId,CAST(GETDATE() AS date),N'ACTIVE');
IF NOT EXISTS (SELECT 1 FROM dbo.USER_FACILITY_ASSIGNMENTS WHERE user_id=@staffId AND facility_id=@facilityId) INSERT dbo.USER_FACILITY_ASSIGNMENTS(assignment_id,user_id,facility_id,assigned_by,start_date,status) VALUES (NEWID(),@staffId,@facilityId,@managerId,CAST(GETDATE() AS date),N'ACTIVE');
IF NOT EXISTS (SELECT 1 FROM dbo.STORAGE_UNIT_TYPES WHERE type_name=N'UC13-14 Demo 5m2') INSERT dbo.STORAGE_UNIT_TYPES(type_name,storage_mode,size_name,width,length,height,features,status) VALUES (N'UC13-14 Demo 5m2',N'STANDARD',N'5 m²',2,2.5,2.8,N'Kho demo UC13/UC14',N'ACTIVE');
SELECT @typeId=type_id FROM dbo.STORAGE_UNIT_TYPES WHERE type_name=N'UC13-14 Demo 5m2';
IF NOT EXISTS (SELECT 1 FROM dbo.STORAGE_UNITS WHERE unit_id=@unitId) INSERT dbo.STORAGE_UNITS(unit_id,facility_id,type_id,unit_number,status) VALUES (@unitId,@facilityId,@typeId,N'UC13-14-DEMO-01',N'AVAILABLE');
SELECT TOP 1 @pricingId=pricing_id FROM dbo.PRICING_POLICIES WHERE facility_id=@facilityId AND type_id=@typeId AND status=N'ACTIVE' ORDER BY effective_from DESC;
IF @pricingId IS NULL BEGIN SET @pricingId=NEWID(); INSERT dbo.PRICING_POLICIES(pricing_id,facility_id,type_id,created_by,monthly_price,deposit_amount,daily_overdue_rate,late_payment_rate,early_termination_fee,discount_rate,fee_waiver_allowed,effective_from,status) VALUES (@pricingId,@facilityId,@typeId,@managerId,1000000,1000000,0,0,0,0,0,'2026-01-01',N'ACTIVE'); END;
IF NOT EXISTS (SELECT 1 FROM dbo.RESERVATIONS WHERE reservation_id=@reservationId) INSERT dbo.RESERVATIONS(reservation_id,customer_id,facility_id,type_id,pricing_id,start_date,end_date,estimated_rental_amount,estimated_deposit_amount,status,created_at) VALUES (@reservationId,@customerId,@facilityId,@typeId,@pricingId,'2026-10-01','2026-12-31',3000000,1000000,N'CONFIRMED',SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM dbo.RENTAL_CONTRACTS WHERE contract_id=@contractId) INSERT dbo.RENTAL_CONTRACTS(contract_id,contract_number,reservation_id,customer_id,unit_id,start_date,end_date,monthly_rental_fee,deposit_amount,billing_cycle,terms_version,customer_signed_at,approved_by,approved_at,status,created_at) VALUES (@contractId,N'HD-DEMO-UC13-14',@reservationId,@customerId,@unitId,'2026-10-01','2026-12-31',1000000,1000000,N'MONTHLY',N'v1',SYSDATETIME(),@managerId,SYSDATETIME(),N'CONFIRMED',SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM dbo.INVOICES WHERE invoice_id=@depositInvoiceId) INSERT dbo.INVOICES(invoice_id,invoice_number,contract_id,invoice_type,description,subtotal,penalty_amount,discount_amount,total_amount,paid_amount,issued_at,due_date,status) VALUES (@depositInvoiceId,N'INV-DEMO-DEP',@contractId,N'DEPOSIT',N'Tiền cọc demo',1000000,0,0,1000000,1000000,SYSDATETIME(),'2026-10-01',N'PAID');
IF NOT EXISTS (SELECT 1 FROM dbo.INVOICES WHERE invoice_id=@rentInvoiceId) INSERT dbo.INVOICES(invoice_id,invoice_number,contract_id,invoice_type,description,subtotal,penalty_amount,discount_amount,total_amount,paid_amount,issued_at,due_date,status) VALUES (@rentInvoiceId,N'INV-DEMO-RENT',@contractId,N'INITIAL_RENT',N'Tiền thuê ban đầu demo',1000000,0,0,1000000,1000000,SYSDATETIME(),'2026-10-01',N'PAID');
IF NOT EXISTS (SELECT 1 FROM dbo.PAYMENT_TRANSACTIONS WHERE transaction_id=@depositPaymentId) INSERT dbo.PAYMENT_TRANSACTIONS(transaction_id,invoice_id,contract_id,transaction_type,payment_type,payment_method,amount,transaction_date,reference_code,status,created_by,idempotency_key,created_at,updated_at) VALUES (@depositPaymentId,@depositInvoiceId,@contractId,N'INITIAL_PAYMENT',N'DEPOSIT',N'BANK_TRANSFER',1000000,SYSDATETIME(),N'DEMO-DEP',N'SUCCESS',@customerId,N'DEMO-DEP',SYSDATETIME(),SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM dbo.PAYMENT_TRANSACTIONS WHERE transaction_id=@rentPaymentId) INSERT dbo.PAYMENT_TRANSACTIONS(transaction_id,invoice_id,contract_id,transaction_type,payment_type,payment_method,amount,transaction_date,reference_code,status,created_by,idempotency_key,created_at,updated_at) VALUES (@rentPaymentId,@rentInvoiceId,@contractId,N'INITIAL_PAYMENT',N'INITIAL_RENT',N'CASH',1000000,SYSDATETIME(),N'DEMO-RENT',N'SUCCESS',@staffId,N'DEMO-RENT',SYSDATETIME(),SYSDATETIME());
IF NOT EXISTS (SELECT 1 FROM dbo.PICKUP_APPOINTMENTS WHERE appointment_id=@appointmentId) INSERT dbo.PICKUP_APPOINTMENTS(appointment_id,contract_id,facility_id,customer_id,appointment_time,assigned_staff_id,status,created_at,updated_at) VALUES (@appointmentId,@contractId,@facilityId,@customerId,'2026-10-14T09:00:00',@staffId,N'SCHEDULED',SYSDATETIME(),SYSDATETIME());
COMMIT TRANSACTION;
GO
SELECT N'UC13/UC14 demo seed ready' AS result, N'manager.demo@safebox.test / password' AS manager_login, N'staff.demo@safebox.test / password' AS staff_login, N'customer.demo@safebox.test / password' AS customer_login, N'HD-DEMO-UC13-14' AS contract_number, N'UC13-14-DEMO-01' AS unit_number;
GO
